const sunLight = new T.PointLight(0xffcc66, 2.6, 0, 0);
scene.add(sunLight);
const earthFillLight = new T.DirectionalLight(0xbfd6ff, 0.0);
scene.add(earthFillLight);
scene.add(earthFillLight.target);
const earthRimLight = new T.DirectionalLight(0x9fc4ff, 0.0);
scene.add(earthRimLight);
scene.add(earthRimLight.target);

if (name === 'Earth') {
  const aspect = width / height;
  const halfV = (48 * Math.PI / 180) / 2;
  const halfH = Math.atan(Math.tan(halfV) * aspect);
  const dist = 1.15 / Math.tan(Math.min(halfV, halfH));
  return { yaw: 0.62, pitch: 0.3, radius: Math.max(1.9, Math.min(5.2, dist)) };
}
return { yaw: name === 'Saturn' ? 0.82 : 0.55, pitch: name === 'Saturn' ? 0.24 : 0.12, radius: name === 'Saturn' ? 8.2 : 2.6 };

camera.position.copy(lookPoint).addScaledVector(tempDir, radius);
camera.lookAt(lookPoint);
camera.updateMatrixWorld();
const earthFocus = mode === 'earth';
earthFillLight.intensity = earthFocus ? 1.25 : 0.0;
earthRimLight.intensity = earthFocus ? 0.35 : 0.0;
if (earthFocus) {
  earthFillLight.position.copy(camera.position);
  earthFillLight.target.position.copy(lookPoint);
  earthFillLight.target.updateMatrixWorld();
  earthRimLight.position.copy(lookPoint).add(new T.Vector3(0, 1.6, 0));
  earthRimLight.target.position.copy(lookPoint);
  earthRimLight.target.updateMatrixWorld();
}
sun.visible = !earthFocus;
ambient.intensity = earthFocus ? 0.34 : 0.5;
sunLight.intensity = earthFocus ? 0.55 : 2.6;
